INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','ellipsis-substitution','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"ellipsis-substitution","title":"Ellipsis, substitution and avoiding repetition","level":"C1","order":64,"summary":"Leave out recoverable words and use substitutes without losing the intended meaning.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Keep the auxiliary, omit repeated content","So and neither for shared experience","One and ones replace count nouns","Substitute for whole propositions"],"rules":[{"title":"Keep the auxiliary, omit repeated content","explanation":"Ellipsis removes words that the listener can recover from context. After a suitable auxiliary, a repeated verb phrase can be omitted. Match the auxiliary to the clause’s tense and structure.","pattern":"She can swim, and I **can too**.","commonMistakes":["I swim and she is too does not match the auxiliary to the lexical verb in the first clause."],"examples":["“I prepare the visitor guide every week.” Add that you do too: “**So do I**.”","“I restore the old portrait every week.” Add that you do too: “**So do I**.”"],"skill":"form"},{"title":"So and neither for shared experience","explanation":"Use **so + auxiliary + subject** to add agreement to a positive statement. Use **neither / nor + auxiliary + subject** after a negative one. This is an inverted agreement pattern, not ordinary statement order.","pattern":"I work here. **So do I.** / I don’t. **Neither do I.**","commonMistakes":["So I do is an emphatic acknowledgement, not the same pattern as So do I."],"examples":["“I do not prepare the visitor guide.” Add that you do not either: “**Neither do I**.”","“I do not restore the old portrait.” Add that you do not either: “**Neither do I**.”"],"skill":"meaning"},{"title":"One and ones replace count nouns","explanation":"One can replace a singular count noun and ones can replace plural count nouns when the noun is understood. They can combine with adjectives or determiners. They do not freely replace uncountable nouns.","pattern":"I prefer the blue **one**. / The old **ones** are cheaper.","commonMistakes":["Some advice → some, not some ones; advice is uncountable in this use."],"examples":["“She can prepare the visitor guide, and we **can** too.”","“She can restore the old portrait, and we **can** too.”"],"skill":"contrast"},{"title":"Substitute for whole propositions","explanation":"So can stand for an affirmative proposition after verbs such as think, hope and expect. Negative forms vary by verb: I hope not, I don’t think so. Such can point back to a type of thing already mentioned. Keep the reference unambiguous.","pattern":"Will it work? I **hope so**.","commonMistakes":["I don’t hope so is not the ordinary negative response; use I hope not."],"examples":["“Will they prepare the visitor guide on time?” Express a positive hope: “I hope **so**.”","“Will they restore the old portrait on time?” Express a positive hope: “I hope **so**.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-ellipsis"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Leave out recoverable words and use substitutes without losing the intended meaning.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Keep the auxiliary, omit repeated content","explanation":"Ellipsis removes words that the listener can recover from context. After a suitable auxiliary, a repeated verb phrase can be omitted. Match the auxiliary to the clause’s tense and structure.","pattern":"She can swim, and I **can too**.","commonMistakes":["I swim and she is too does not match the auxiliary to the lexical verb in the first clause."],"examples":["“I prepare the visitor guide every week.” Add that you do too: “**So do I**.”","“I restore the old portrait every week.” Add that you do too: “**So do I**.”"],"skill":"form","id":"ellipsis-substitution-foundation-1","domain":"reference","referenceIds":["bc-ellipsis"],"readingVersion":"core-2026-09-v3"},{"title":"So and neither for shared experience","explanation":"Use **so + auxiliary + subject** to add agreement to a positive statement. Use **neither / nor + auxiliary + subject** after a negative one. This is an inverted agreement pattern, not ordinary statement order.","pattern":"I work here. **So do I.** / I don’t. **Neither do I.**","commonMistakes":["So I do is an emphatic acknowledgement, not the same pattern as So do I."],"examples":["“I do not prepare the visitor guide.” Add that you do not either: “**Neither do I**.”","“I do not restore the old portrait.” Add that you do not either: “**Neither do I**.”"],"skill":"meaning","id":"ellipsis-substitution-foundation-2","domain":"reference","referenceIds":["bc-ellipsis"],"readingVersion":"core-2026-09-v3"},{"title":"One and ones replace count nouns","explanation":"One can replace a singular count noun and ones can replace plural count nouns when the noun is understood. They can combine with adjectives or determiners. They do not freely replace uncountable nouns.","pattern":"I prefer the blue **one**. / The old **ones** are cheaper.","commonMistakes":["Some advice → some, not some ones; advice is uncountable in this use."],"examples":["“She can prepare the visitor guide, and we **can** too.”","“She can restore the old portrait, and we **can** too.”"],"skill":"contrast","id":"ellipsis-substitution-foundation-3","domain":"reference","referenceIds":["bc-ellipsis"],"readingVersion":"core-2026-09-v3"},{"title":"Substitute for whole propositions","explanation":"So can stand for an affirmative proposition after verbs such as think, hope and expect. Negative forms vary by verb: I hope not, I don’t think so. Such can point back to a type of thing already mentioned. Keep the reference unambiguous.","pattern":"Will it work? I **hope so**.","commonMistakes":["I don’t hope so is not the ordinary negative response; use I hope not."],"examples":["“Will they prepare the visitor guide on time?” Express a positive hope: “I hope **so**.”","“Will they restore the old portrait on time?” Express a positive hope: “I hope **so**.”"],"skill":"application","id":"ellipsis-substitution-foundation-4","domain":"reference","referenceIds":["bc-ellipsis"],"readingVersion":"core-2026-09-v3"},{"domain":"reference","id":"one-ones-and-other","title":"One, ones, other, another and the others","explanation":"One and ones can replace a count noun while retaining its modifiers. Another usually means one additional or different member; other precedes a plural or non-count noun, while others stands without a following noun. The identifies a contextually recoverable remainder or alternative. These forms combine reference with number and definiteness.","pattern":"the red **one** / the smaller **ones**","examples":["Some stayed; **the others** left.","I’d like **another cup**, but no **other food**."],"commonMistakes":["One does not normally replace an ordinary non-count noun: I need fresh water, not a cold one, unless one means a count serving or a container in context."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"reference","id":"anaphora-cataphora","title":"Looking backward and forward in a text","explanation":"Reference can look back to an earlier expression, forward to an explanation, or outward to the shared situation. A repeated noun, pronoun or demonstrative links clauses into a coherent text. Keep the intended referent close enough and specific enough for the reader to identify it. Whole propositions can also be referred to with this, that or so.","pattern":"**This** is the problem: the key does not fit.","examples":["Although **she** was tired, **Nadia** finished the report.","The train was cancelled. **That** changed our plans."],"commonMistakes":["A pronoun before a name is possible in some structures, but forward reference is not unrestricted: He says that Tom is ready normally does not make he and Tom the same person."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"usage","id":"spoken-ellipsis","title":"Conversational ellipsis and recoverable subjects","explanation":"Speech often omits material recoverable from the situation: Want a coffee? for Do you want a coffee? Short replies omit repeated predicates. Context makes these expressions understandable. Formal standalone writing usually needs more explicit structure, while dialogue, messages and headings can use appropriate reductions.","pattern":"**Seen Maya?** / **Sounds good.**","examples":["A: Who wants tea? B: **I do**.","A: When are you leaving? B: **Tomorrow**."],"commonMistakes":["Omission is constrained by grammar and recoverability. It is not permission to delete arbitrary words from a sentence or leave a formal argument without a clear subject."],"referenceIds":["cambridge-spoken","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["She can swim, and I **can too**.","I work here. **So do I.** / I don’t. **Neither do I.**","I prefer the blue **one**. / The old **ones** are cheaper.","Will it work? I **hope so**."],"readingVersion":"core-2026-09-v4"},"stage":"6 · Advanced control","prerequisites":["clefts-emphasis"],"readingReferenceIds":["bc-ellipsis","cambridge-comprehensive-scope","cambridge-spoken"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='ellipsis-substitution'
